pub(crate) fn rule_name(tag: u32) -> Option<&'static str> {
    RULE_NAMES.get(tag as usize).copied()
}
pub(crate) fn terminal_name(tag: u32) -> Option<&'static str> {
    TERMINAL_NAMES.get(tag as usize).copied()
}
